draw(A--B--C--A--E--D--F--B--C--D);
draw(M--N--P--Q--M, dashed);
label("$A$", A, NW);
label("$B$", B, NE);
label("$C$", C, dir(90));
label("$D$", D, S);
label("$E$", E, SW);
label("$F$", F, SE);
label("$M$", M, SW);
label("$N$", N, SE);
label("$P$", P, SE);
